#include <stdlib.h>
#include <string.h>

/* sorts a[0..n-1], all values in [0, k]; returns 0 on success */
int counting_sort(int a[], int n, int k) {
    int *count = calloc((size_t)k + 1, sizeof *count);
    int *out = malloc((size_t)n * sizeof *out);
    if (!count || !out) { free(count); free(out); return -1; }

    for (int i = 0; i < n; i++) count[a[i]]++;           /* histogram */
    for (int v = 1; v <= k; v++) count[v] += count[v - 1]; /* prefix */
    for (int i = n - 1; i >= 0; i--)                     /* stable */
        out[--count[a[i]]] = a[i];

    memcpy(a, out, (size_t)n * sizeof *a);
    free(count); free(out);
    return 0;
}

/* alternative: exclusive prefix sums, forward scan, also stable */
int start = 0;
for (int v = 0; v <= k; v++) {
    int c = count[v];
    count[v] = start;        /* first output index for key v */
    start += c;
}
for (int i = 0; i < n; i++)
    out[count[a[i]]++] = a[i];

int counting_sort_range(int a[], int n) {
    int mn = a[0], mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < mn) mn = a[i];
        if (a[i] > mx) mx = a[i];
    }
    long long range = (long long)mx - mn + 1;
    if (range > 100000000LL) return -2;          /* refuse huge tables */
    int *count = calloc((size_t)range, sizeof *count);
    int *out = malloc((size_t)n * sizeof *out);
    if (!count || !out) { free(count); free(out); return -1; }
    for (int i = 0; i < n; i++) count[a[i] - mn]++;
    for (long long v = 1; v < range; v++) count[v] += count[v - 1];
    for (int i = n - 1; i >= 0; i--) out[--count[a[i] - mn]] = a[i];
    memcpy(a, out, (size_t)n * sizeof *a);
    free(count); free(out);
    return 0;
}

struct rec { int grade; char name[16]; };

void sort_by_grade(struct rec *in, struct rec *out, int n) {
    int count[101] = {0};                     /* grades 0..100 */
    for (int i = 0; i < n; i++) count[in[i].grade]++;
    for (int g = 1; g <= 100; g++) count[g] += count[g - 1];
    for (int i = n - 1; i >= 0; i--)
        out[--count[in[i].grade]] = in[i];    /* copies whole record */
}

void radix_sort_u32(unsigned a[], unsigned tmp[], int n) {
    for (int shift = 0; shift < 32; shift += 8) {
        int count[256] = {0};
        for (int i = 0; i < n; i++) count[(a[i] >> shift) & 0xFF]++;
        for (int v = 1; v < 256; v++) count[v] += count[v - 1];
        for (int i = n - 1; i >= 0; i--)
            tmp[--count[(a[i] >> shift) & 0xFF]] = a[i];
        for (int i = 0; i < n; i++) a[i] = tmp[i];
    }
}
